 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
+#if defined(__ARM_NEON)
+    size_t len = n;
+    int64_t* restrict in_ptr = in;
+    int64_t* restrict out_ptr = out;
+    uint64_t* restrict hist_ptr = hist;
+
+    // Align lengths to fit into NEON vectors.
+    size_t aligned_len = ((len + 7) / 16) * 16;
+    size_t remainder = aligned_len - len;
+
+    // Process the first part using NEON intrinsics.
+    int64x8_t vsum = vdupq_n_s64(0);
+    uint64x8_t vhist = vdupq_n_u64(0);
+    for (size_t i = 0; i < aligned_len; i += 16) {
+        int64x8_t vin = vld1q_s64(in_ptr + i);
+        vsum = vaddq_s64(vsum, vin);
+        vhist = vcntq_u64(vin, vhist);
+        vst1q_s64(out_ptr + i, vsum);
+        out_ptr += 16;
+        in_ptr += 16;
+    }
+
+    // Process the remainder using scalar operations.
+    for (size_t i = aligned_len; i < n; i += 16) {
+        int64_t sum = 0;
+        for (int j = 0; j < 16 && i < n; ++j, ++i) {
+            sum += in[i];
+            out[i] = sum;
+            hist[in[i] & 255]++;
+        }
+    }
+
+    // Further optimize by processing the histogram with NEON
+    // Counting the histogram with NEON
+    uint64x8_t low_byte = vdupq_n_u64(255);
+    for (size_t i = 0; i < aligned_len; i += 16) {
+        int64x8_t vin_temp = vld1q_s64(in_ptr + i);
+        uint8x8_t byte_mask = vandq_u8(vin_temp, low_byte);
+        vhist = vbicq_u64(vhist, byte_mask, vhist);
+        vst1q_u64(hist_ptr + (i / 2), vhist);
+    }
+
+    // Process the remainder for histogram using scalar operations
+    for (size_t i = aligned_len; i < n; ++i) {
+        hist[in[i] & 255]++;
+    }
+
+#else
     for (int b = 0; b < 256; ++b) hist[b] = 0;
